import java.math.BigInteger
import java.util.*

const val MOD = 1000000007

fun modPow(a: Long, e: Long): Long {
    var base = a % MOD
    var exp = e
    var res = 1L
    while (exp > 0) {
        if (exp and 1L == 1L) res = res * base % MOD
        base = base * base % MOD
        exp = exp shr 1
    }
    return res
}

fun modInv(a: Long): Long = modPow(a, MOD - 2)

fun mulMod(a: Long, b: Long): Long = (a * b) % MOD

fun addMod(a: Long, b: Long): Long {
    val res = a + b
    return if (res >= MOD) res - MOD else res
}

fun subMod(a: Long, b: Long): Long {
    val res = a - b
    return if (res < 0) res + MOD else res
}

fun pollardRho(n: Long): Long {
    if (n % 2L == 0L) return 2L
    if (n % 3L == 0L) return 3L
    val rand = Random(58)
    while (true) {
        val c = (rand.nextLong() % (n - 1) + 1).absoluteValue
        val f = { x: Long -> (mulMod(x, x, n) + c) % n }
        var x = (rand.nextLong() % (n - 2) + 2).absoluteValue
        var y = x
        var d = 1L
        while (d == 1L) {
            x = f(x)
            y = f(f(y))
            d = (x - y).absoluteValue.gcd(n)
        }
        if (d != n) return d
    }
}

fun mulMod(a: Long, b: Long, mod: Long): Long {
    return (BigInteger.valueOf(a).multiply(BigInteger.valueOf(b)).mod(BigInteger.valueOf(mod))).longValue()
}

fun isPrime(n: Long): Boolean {
    if (n < 2) return false
    if (n % 2L == 0L) return n == 2L
    if (n % 3L == 0L) return n == 3L
    val d = n - 1
    var s = 0
    var t = d
    while (t % 2L == 0L) {
        t /= 2L
        s++
    }
    val bases = arrayOf(2L, 325L, 9375L, 28178L, 450775L, 9780504L, 1795265022L)
    for (a in bases) {
        if (a % n == 0L) continue
        var x = modPow(a, t, n)
        if (x == 1L || x == n - 1) continue
        var composite = true
        for (i in 1 until s) {
            x = mulMod(x, x, n)
            if (x == n - 1) {
                composite = false
                break
            }
        }
        if (composite) return false
    }
    return true
}

fun modPow(a: Long, e: Long, mod: Long): Long {
    var base = a % mod
    var exp = e
    var res = 1L
    while (exp > 0) {
        if (exp and 1L == 1L) res = mulMod(res, base, mod)
        base = mulMod(base, base, mod)
        exp = exp shr 1
    }
    return res
}

fun factor(n: Long, res: MutableMap<Long, Int>) {
    if (n == 1L) return
    if (isPrime(n)) {
        res[n] = res.getOrDefault(n, 0) + 1
        return
    }
    val d = pollardRho(n)
    factor(d, res)
    factor(n / d, res)
}

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextLong()
    val k = scanner.nextInt()

    val factors = mutableMapOf<Long, Int>()
    factor(n, factors)

    val maxE = factors.values.maxOrNull() ?: 0
    val maxSize = maxE + 1

    // Precompute factorials and inverse factorials up to maxE + k (actually we need up to maxE)
    // For transition matrix, we need binomial coefficients C(j, i) for 0 <= i <= j <= maxE.
    // We can precompute factorials up to maxE.
    val fact = LongArray(maxE + 1)
    val invFact = LongArray(maxE + 1)
    fact[0] = 1
    for (i in 1..maxE) fact[i] = mulMod(fact[i - 1], i.toLong())
    invFact[maxE] = modInv(fact[maxE])
    for (i in maxE downTo 1) invFact[i - 1] = mulMod(invFact[i], i.toLong())

    fun C(n: Int, k: Int): Long {
        if (k < 0 || k > n) return 0L
        return mulMod(fact[n], mulMod(invFact[k], invFact[n - k]))
    }

    var ans = 1L
    for ((p, e) in factors) {
        // Build transition matrix T of size (e+1) x (e+1)
        // State vector represents probabilities of exponent being 0..e
        // T[i][j] = probability to go from exponent j to exponent i
        // From j, choose divisor uniformly among j+1 possibilities (exponents 0..j)
        // So T[i][j] = 1/(j+1) for i <= j, else 0.
        val size = e + 1
        // We need to compute T^k * v0 where v0 is [0,0,...,1] (exponent e)
        // Then expected value = sum_{i=0}^e (p^i) * prob_i
        // We can do matrix exponentiation on the transition matrix.
        // But size <= maxE+1. maxE for n<=1e15 is at most ~50 (2^50 > 1e15).
        // k <= 1e4. Matrix exponentiation O(size^3 log k) is fine (size <= 60).

        // Construct matrix as list of lists
        val mat = Array(size) { LongArray(size) }
        for (j in 0..e) {
            val inv = modInv((j + 1).toLong())
            for (i in 0..j) {
                mat[i][j] = inv
            }
        }

        // Matrix exponentiation
        fun multiply(A: Array<LongArray>, B: Array<LongArray>): Array<LongArray> {
            val sz = A.size
            val C = Array(sz) { LongArray(sz) }
            for (i in 0 until sz) {
                for (k2 in 0 until sz) {
                    if (A[i][k2] == 0L) continue
                    val aik = A[i][k2]
                    for (j in 0 until sz) {
                        C[i][j] = addMod(C[i][j], mulMod(aik, B[k2][j]))
                    }
                }
            }
            return C
        }

        fun matPow(base: Array<LongArray>, exp: Int): Array<LongArray> {
            val sz = base.size
            var result = Array(sz) { LongArray(sz) }
            for (i in 0 until sz) result[i][i] = 1L
            var b = base
            var e = exp
            while (e > 0) {
                if (e and 1 == 1) result = multiply(result, b)
                b = multiply(b, b)
                e = e shr 1
            }
            return result
        }

        val matK = matPow(mat, k)
        // Initial vector: column vector with 1 at index e
        // Result vector = matK * v0 => column e of matK
        var expected = 0L
        var pPow = 1L
        for (i in 0..e) {
            val prob = matK[i][e]
            expected = addMod(expected, mulMod(pPow, prob))
            pPow = mulMod(pPow, p % MOD)
        }
        ans = mulMod(ans, expected)
    }
    println(ans)
}
